package dev.redstoneengineering.block;
import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.BlockGetter;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.block.state.StateDefinition;import net.minecraft.world.level.block.state.properties.EnumProperty;import net.minecraft.world.phys.shapes.CollisionContext;import net.minecraft.world.phys.shapes.VoxelShape;
/** Straight 3-D cable segment. Turns/branches are explicit Junction blocks. */
public abstract class AxialCableBlock extends DomainBlock{public static final EnumProperty<Direction.Axis> AXIS=EnumProperty.create("axis",Direction.Axis.class);private static final VoxelShape X=Block.box(0,6,6,16,10,10),Y=Block.box(6,0,6,10,16,10),Z=Block.box(6,6,0,10,10,16);protected AxialCableBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(AXIS,Direction.Axis.X));}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(AXIS);}@Override public BlockState getStateForPlacement(BlockPlaceContext c){Direction.Axis a;if(c.getPlayer()!=null&&c.getPlayer().isShiftKeyDown())a=Direction.Axis.Y;else if(c.getClickedFace().getAxis()!=Direction.Axis.Y)a=c.getClickedFace().getAxis();else a=c.getHorizontalDirection().getAxis();return defaultBlockState().setValue(AXIS,a);}@Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return switch(s.getValue(AXIS)){case X->X;case Y->Y;case Z->Z;};}}
